","timestamp":"2026-11-01T21:00:00.123Z","targetId":"c1","replacement":null},"messages":[]}],"messages":[{"role":"user","content":"Edited U2","timestamp":1793566800123},{"role":"assistant","content":[{"type":"text","text":"Edited A2"}],"api":"openai-responses","provider":"openai","model":"fixture","timestamp":1793566800123,"usage":{"input":2,"output":3},"stopReason":"stop"},{"role":"user","content":[{"type":"text","text":"U3"}],"timestamp":1793566800123}],"thinkingLevel":"high","model":{"provider":"openai","modelId":"fixture"}},"llm":[{"role":"user","content":"Edited U2","timestamp":1793566800123},{"role":"assistant","content":[{"type":"text","text":"Edited A2"}],"api":"openai-responses","provider":"openai","model":"fixture","timestamp":1793566800123,"usage":{"input":2,"output":3},"stopReason":"stop"},{"role":"user","content":[{"type":"text","text":"U3"}],"timestamp":1793566800123}]}}]}"""
context_oracle() = isempty(get(ENV,"JF2_CONTEXT_ORACLE","")) ? JSON.parse(CONTEXT_CAPTURE) : JSON.parsefile(ENV["JF2_CONTEXT_ORACLE"])
function context_json(projection)
    Dict("messages"=>projection.messages,"thinkingLevel"=>projection.thinking_level,"model"=>projection.model)
end
function projection_json(projection)
    merge(context_json(projection),Dict("entries"=>[Dict("sourceEntry"=>entry.source_entry,"messages"=>entry.messages) for entry in projection.entries]))
end
@testset "Original Pi effective-context differential" begin
    oracle=context_oracle()
    @test oracle["pin"]=="2c8d1feb147f6b3d97e855da803bfe7b19f3c403"
    for fixture in oracle["cases"]
        @testset "$(fixture["name"])" begin
            original=deepcopy(fixture["entries"])
            projection=TC.timeline_projection(fixture["entries"];leaf=get(fixture,"leaf",missing))
            @test context_json(projection)==fixture["expected"]["context"]
            @test projection_json(projection)==fixture["expected"]["projection"]
            @test TC.timeline_llm_messages(projection)==fixture["expected"]["llm"]
            @test fixture["entries"]==original
        end
    end
end

@testset "Projection snapshots, active branches and native text transport" begin
    fixture=only(filter(x -> x["name"]=="compaction-edits",context_oracle()["cases"]))
    header=TC.timeline_header(TC.SessionTimeline("/tmp"))
    timeline=TC.timeline_from_rows([header;fixture["entries"]])
    archive=TC.timeline_entries(timeline)
    selected=TC.timeline_projection(timeline)
    @test TC.timeline_context(timeline).messages==selected.messages
    native=TC.timeline_runtime_messages(selected)
    @test [message.role for message in native]==[:system,:user,:user,:assistant,:user]
    @test [TC.wire_content(message) for message in native]==[message.content for message in native]
    @test all(message -> message.metadata isa TC.TimelineMessageMetadata,native)
    @test native[2].metadata.source_entry_id=="c1"
    @test native[4].metadata.projected["usage"]==Dict("input"=>2,"output"=>3)
    selected.entries[1].source_entry["summary"]="tampered"
    selected.messages[1]["content"]="tampered"
    @test TC.timeline_entries(timeline)==archive
    @test selected.entries[1].messages[1]["content"]=="System checkpoint"
    native[1].metadata.projected["content"]="separate"
    @test TC.timeline_entries(timeline)==archive
    TC.timeline_branch!(timeline,nothing)
    @test isempty(TC.timeline_projection(timeline).messages)
    TC.timeline_branch!(timeline,"u1")
    @test TC.timeline_projection(timeline).model==Dict("provider"=>"openai","modelId"=>"before")
    @test length(TC.timeline_runtime_messages(timeline))==2
    @test_throws ErrorException TC.timeline_projection(timeline;leaf="missing")
    @test TC.timeline_entries(timeline)==archive
    for millis in (0,1,-1,-86400001,951782400123,4107542399999,1793566800123)
        @test TC.timeline_epoch_milliseconds(TC.timeline_timestamp(millis/1000))==millis
    end
    @test TC.timeline_epoch_milliseconds("2026-11-01T21:00:00.123999Z")==1793566800123
    @test_throws ErrorException TC.timeline_epoch_milliseconds("2026-02-30T00:00:00Z")
end

@testset "Native Message archival and wire-equivalent restoration" begin
    examples=Message[
        Message(:user,"question"),
        Message(:assistant,"answer",:answer),
        Message(:assistant,"x=42",:code),
        Message(:code_result,"42";metadata=TC.ExecutionResult(true,"42",42)),
        Message(:code_result,"failed";metadata=TC.ExecutionResult(false,"failed",nothing)),
        Message(:user,"with metadata";metadata=Dict("source"=>"fixture","flags"=>[1,true])),
        Message(:system,"system instruction")]
    for message in examples
        raw=TC.timeline_archive_message(message;timestamp=0)
        timeline=TC.SessionTimeline("/tmp")
        TC.timeline_append_message!(timeline,raw)
        restored=only(TC.timeline_runtime_messages(timeline))
        @test restored.role==message.role
        @test restored.kind==message.kind
        @test restored.content==message.content
        @test TC.wire_content(restored)==TC.wire_content(message)
        @test !haskey(raw,"toolCallId")
        @test TC.timeline_archive_message(restored;timestamp=0)==raw
    end
    result=TC.timeline_archive_message(Message(:code_result,"callable";metadata=TC.ExecutionResult(true,"callable",identity)))
    @test haskey(result["jf2"]["metadata"],"transientValueType")
    @test !haskey(result["jf2"]["metadata"],"value")
    restored=TC.timeline_native_message(TC.timeline_llm_message(result),"result",result)
    @test restored.metadata isa TC.ExecutionResult
    @test restored.metadata.value===nothing
    @test TC.wire_content(restored)==TC.wire_content(Message(:code_result,"callable";metadata=TC.ExecutionResult(true,"callable",identity)))
    @test_throws ErrorException TC.timeline_archive_message(Message(:assistant,"opaque",:action;metadata=identity))
    @test_throws ErrorException TC.timeline_archive_message(Message(:tool,"no call id"))
    provider=Dict("role"=>"assistant","content"=>[Dict("type"=>"thinking","thinking"=>"opaque","thinkingSignature"=>"sig")],"usage"=>Dict("input"=>12,"output"=>4))
    raw=TC.timeline_archive_message(Message(:assistant,"answer",:answer);provider_message=provider)
    @test raw["jf2"]["providerMessage"]==provider
    provider["usage"]["input"]=999
    @test raw["jf2"]["providerMessage"]["usage"]["input"]==12
    @test_throws ErrorException TC.timeline_archive_message(Message(:user,"question");provider_message=provider)
    @test_throws ErrorException TC.timeline_archive_message(Message(:assistant,"answer");provider_message=Dict("role"=>"user"))
end

@testset "Explicit rich-block and tool adapter boundaries" begin
    cases=context_oracle()["cases"]
    rich=only(filter(x -> x["name"]=="rich",cases))
    projection=TC.timeline_projection(rich["entries"])
    @test_throws ErrorException TC.timeline_runtime_messages(projection)
    for block in [Dict("type"=>"image","data"=>"AQID"),Dict("type"=>"thinking","thinking"=>"opaque"),Dict("type"=>"toolCall","id"=>"x"),Dict("type"=>"new-extension")]
        @test_throws ErrorException TC.timeline_native_message(Dict("role"=>"user","content"=>[block]),"fixture")
    end
    tool=Dict("role"=>"toolResult","toolCallId"=>"x","content"=>[Dict("type"=>"text","text"=>"result")])
    @test_throws ErrorException TC.timeline_native_message(tool,"fixture")
    @test_throws ErrorException TC.timeline_llm_message(Dict("role"=>"unknown","content"=>"opaque"))
    @test_throws ErrorException TC.timeline_runtime_messages(projection;mapper=(raw,id,original)->nothing)
    mapped=TC.timeline_runtime_messages(projection;mapper=(raw,id,original)->Message(:user,JSON.json(raw);metadata=Dict("id"=>id,"original"=>original)))
    @test length(mapped)==length(TC.timeline_llm_messages(projection))
    @test any(message -> occursin("toolCall",message.content),mapped)
    text=Dict("role"=>"user","content"=>[Dict("type"=>"text","text"=>"A"),Dict("type"=>"text","text"=>"B")],"timestamp"=>0)
    native=TC.timeline_native_message(text,"text")
    @test native.content=="AB"
    @test TC.timeline_archive_message(native)==text
    @test_throws ErrorException TC.timeline_archive_message(Message(:user,"changed";metadata=native.metadata))
    spoof=TC.timeline_archive_message(Message(:user,"question"))
    spoof["jf2"]["role"]="assistant"
    @test_throws ErrorException TC.timeline_native_message(spoof,"spoof")
    @test_throws ErrorException TC.timeline_restored_metadata(Dict("format"=>"unknown"))
end

@testset "Projection validation is nonmutating" begin
    fixture=deepcopy(only(filter(x -> x["name"]=="plain",context_oracle()["cases"]))["entries"])
    bad=deepcopy(fixture);bad[2]["parentId"]="missing"
    @test_throws ErrorException TC.timeline_projection(bad)
    bad=deepcopy(fixture);bad[2]["id"]=bad[1]["id"]
    @test_throws ErrorException TC.timeline_projection(bad)
    bad=deepcopy(fixture);bad[2]["data"]=NaN
    @test_throws ErrorException TC.timeline_projection(bad)
    @test TC.timeline_context(fixture;leaf=nothing).thinking_level=="off"
    @test TC.timeline_context(fixture;leaf=nothing).model===nothing
    first=TC.timeline_projection(fixture)
    second=TC.timeline_context(first)
    second.messages[1]["content"]="different"
    @test first.messages[1]["content"]=="Original system"
    @test fixture[1]["message"]["content"]=="Original system"
end

@testset "Exact aligned runtime provenance including synthetic and hidden messages" begin
    cases=context_oracle()["cases"]
    fixture=only(filter(x -> x["name"]=="compaction-edits",cases))
    projection=TC.timeline_projection(fixture["entries"])
    mapping=TC.timeline_runtime_mapping(projection)
    @test mapping.entry_ids==["c1","c1","u2","a2","u3"]
    @test length(mapping.messages)==length(mapping.entry_ids)
    @test TC.timeline_runtime_entry_ids(projection)==mapping.entry_ids
    @test [message.content for message in TC.timeline_runtime_messages(projection)]==[message.content for message in mapping.messages]
    header=TC.timeline_header(TC.SessionTimeline("/tmp"))
    timeline=TC.timeline_from_rows([header;fixture["entries"]])
    @test TC.timeline_runtime_entry_ids(timeline)==mapping.entry_ids
    @test isempty(TC.timeline_runtime_messages(timeline;leaf=nothing))
    @test TC.timeline_runtime_entry_ids(timeline;leaf="u1")==["system","u1"]
    rich=TC.timeline_projection(only(filter(x -> x["name"]=="rich",cases))["entries"])
    converted=TC.timeline_runtime_mapping(rich;mapper=(raw,id,original)->Message(:user,JSON.json(raw)))
    @test "hidden" in converted.entry_ids
    @test "bash" in converted.entry_ids
    @test !("bashhidden" in converted.entry_ids)
    @test !("empty-summary" in converted.entry_ids)
    @test length(converted.entry_ids)==length(converted.messages)
    @test_throws ErrorException TC.timeline_runtime_entry_ids(rich)
end

@testset "Actual assistant provider identity survives contextual projection" begin
    provider=Dict("role"=>"assistant","content"=>[Dict("type"=>"text","text"=>"raw response")],"provider"=>"openai","model"=>"gpt-fixture","api"=>"openai-responses","usage"=>Dict("input"=>3,"output"=>7),"stopReason"=>"stop")
    raw=TC.timeline_archive_message(Message(:assistant,"answer",:answer);provider_message=provider)
    @test raw["provider"]=="openai"
    @test raw["model"]=="gpt-fixture"
    @test raw["usage"]==provider["usage"]
    timeline=TC.SessionTimeline("/tmp")
    TC.timeline_append_message!(timeline,raw)
    @test TC.timeline_context(timeline).model==Dict("provider"=>"openai","modelId"=>"gpt-fixture")
    @test only(TC.timeline_runtime_messages(timeline)).content=="answer"
    manual=TC.timeline_archive_message(Message(:assistant,"answer",:answer);provider=:openai,model="gpt-fixture",api="openai-responses")
    @test manual["provider"]=="openai"
    @test manual["model"]=="gpt-fixture"
    @test_throws ErrorException TC.timeline_archive_message(Message(:assistant,"answer");provider_message=provider,model="different")
    @test_throws ErrorException TC.timeline_archive_message(Message(:user,"question");provider="openai")
    @test_throws ErrorException TC.timeline_archive_message(Message(:assistant,"answer");model="")
end

@testset "Synthetic summary context cannot masquerade as an appended message" begin
    projection=TC.timeline_projection(only(filter(x -> x["name"]=="compaction-edits",context_oracle()["cases"]))["entries"])
    summary=TC.timeline_runtime_messages(projection)[2]
    @test summary.metadata.projected["role"]=="compactionSummary"
    @test_throws ErrorException TC.timeline_archive_message(summary)
end

@testset "Signed and extended text require a provider-native replay adapter" begin
    for key in ("textSignature","cache_control","futureProviderData")
        block=Dict("type"=>"text","text"=>"signed",key=>"opaque")
        @test_throws ErrorException TC.timeline_native_message(Dict("role"=>"assistant","content"=>[block]),"signed")
    end
end
